/// <summary>
///     This private method attaches pdf file from LACArchive associated with record. Returns file name if successfull.
/// </summary>
/// <param name = "_record">Record identifier that LACArchive is attached to</param>
/// <param name = "context">LACContext object</param>
/// <param name = "_showWarning">Show warning flag</param>
private static str LACAttachLastArchivePDFTutorialLocal(Common _record, LACContext context, boolean _showWarning = false)
{
    if (!_record.RecId)
    {
        if (_showWarning)
        {
            warning(strFmt('Unable to find %1 record id %2', tableId2Name(_record.TableId), _record.RecId));
        }
        return '';
    }
    if (context.parmPrintSettings().lacDestinationSettings().skipDelivery())
    {
        if (_showWarning)
        {
            warning(strFmt('Attachment for %1 record id %2 was found, but skip delivery is triggered.', tableId2Name(_record.TableId), _record.RecId));
        }
        return '';
    }
    LACArchive archive = LACArchive::findLastArchive(_record);
    if (!archive)
    {
        if (_showWarning)
        {
            warning(strFmt('Unable to find archive for %1, record id %2', tableId2Name(_record.TableId), _record.RecId));
        }
        return '';
    }
    LACArchiveData archiveData = LACArchiveData::find(archive.Id, LACFileType::PDF);
    if (!archiveData)
    {
        if (_showWarning)
        {
            warning(strFmt('Unable to find PDF file reference record for %1 attachment, record id %2', tableId2Name(_record.TableId), _record.RecId));
        }
        return '';
    }
    LACAttachmentFile attachmentFile = archiveData.attachmentFile();
    if (!attachmentFile.existsOnAnyStorage())
    {
        if (_showWarning)
        {
            warning(strFmt('Unable to find PDF file in storage for %1 attachment, record id %2', tableId2Name(_record.TableId), _record.RecId));
        }
        return '';
    }

    str dataSourceName;
    if (context.parmValueSegment() && context.parmValueSegment().parent()) // Initializing dataSourceName from valueSegment
    {
        LACValueSegment parentSegment = context.parmValueSegment().parent();
        if (!(parentSegment is LACValueSegment_RelatedSource))
        {
            if (_showWarning)
            {
                warning(strFmt('Unable to find datasource for %1 attachment, record id %2', tableId2Name(_record.TableId), _record.RecId));
            }
            return '';
        }
        dataSourceName = parentSegment.getDisplayValue();
    }
    else if (context.parmLACReportElement()) // Initializing dataSourceName from valueSegment
    {
        dataSourceName = context.parmLACReportElement().getReturnDSName(context.argsCache());
    }
    if (!dataSourceName)
    {
        if (_showWarning)
        {
            warning(strFmt('Unable to find datasource for %1 attachment, record id %2', tableId2Name(_record.TableId), _record.RecId));
        }
        return '';
    }
    LACRecordMap setupMap = context.parmCustomCode().docuRefLineAttachmentSettings(dataSourceName, context.parmPostProcessing()?context.parmPostProcessing().getDocumentType():LACOverlayDocumentType::None);
    LACDocuRefSetup docuRefSetup;
    boolean attached;
    if (setupMap)
    {
        LACRecordMapEnumerator setupMapEnumerator = setupMap.getEnumerator();
        while(setupMapEnumerator.moveNext())
        {
            docuRefSetup = setupMapEnumerator.currentValue();
            LACAttachWithInstruction attachWithInstruction = LACAttachWithInstruction::newAttachWithInstruction(attachmentFile, docuRefSetup.AttachmentDeliveryMode);
            if (docuRefSetup.ActiveCustomPort && docuRefSetup.ActiveFax && docuRefSetup.ActivePDF && docuRefSetup.ActivePrinter)
            {
                context.attachFile(attachWithInstruction);
                attached = true;
            }
            else
            {
                if (docuRefSetup.ActiveCustomPort)
                {
                    attachmentFile.onlyToDestinationType = LACDestTypes4Print::CustomPort;
                    context.attachFile(attachWithInstruction);
                    attached = true;
                }
                if (docuRefSetup.ActiveFax)
                {
                    attachmentFile.onlyToDestinationType = LACDestTypes4Print::Fax;
                    context.attachFile(attachWithInstruction);
                    attached = true;
                }
                if (docuRefSetup.ActivePDF)
                {
                    attachmentFile.onlyToDestinationType = LACDestTypes4Print::Email;
                    context.attachFile(attachWithInstruction);
                    attached = true;
                }
                if (docuRefSetup.ActivePrinter)
                {
                    attachmentFile.onlyToDestinationType = LACDestTypes4Print::Printer;
                    context.attachFile(attachWithInstruction);
                    attached = true;
                }
            }
        }
    }
    else
    {

        if (_showWarning)
        {
            warning(strFmt('Unable to find Report Attachment setup for %1 attachment, record id %2', tableId2Name(_record.TableId), _record.RecId));
        }
    }

    if (!attached)
    {
        return '';
    }
    // context.attachFile(attachmentFile);
    return attachmentFile.fileNameOnly();
}

/// </summary>
/// <param name = "_record">Record identifier that LACArchive is attached to</param>
/// <param name = "context">LACContext object</param>
public static str LACAttachLastArchivePDFTutorial(Common _record, LACContext context)
{
    return LACTutorialContextMethodsTutorial_Tutorial::LACAttachLastArchivePDFTutoriallocal(_record, context);
}

/// <summary>
///     This method attaches pdf file from LACArchive associated with record. Shows infolog warning if not successfull.
/// </summary>
/// <param name = "_record">Record identifier that LACArchive is attached to</param>
/// <param name = "context">LACContext object</param>
public static void LACAttachLastArchivePDFWithWarningTutorial(Common _record, LACContext context)
{
    str fileAttached = LACTutorialContextMethodsTutorial_Tutorial::LACAttachLastArchivePDFTutorialLocal(_record, context, true);
    if (!fileAttached)
    {
        warning(strFmt('Unable to find archive or file is not present for %1, record id %2', tableId2Name(_record.TableId), _record.RecId));
    }
}

// Adding attachment from docuRef as URL
[LACReportElementPropertiesAttribute('Add current DocuRef attachment as URL'),
 LACValueSourceAttribute(staticmethodStr(LACTutorialContextMethodsTutorial_Tutorial, LACAttachCurrentAsURLTutorial), 'Add current DocuRef attachment as URL'),
 SuppressBpWarning('BPParameterNotUsed', 'First parameter is used to link to common table records')] // Label must be provided without prefix, language text can be added directly
public static void LACAttachCurrentAsURLTutorial(DocuRef docuRef, LACContext context)
{
    if (!docuRef || !docuRef.isValueAttached() || !context.parmCustomCode())
    {
        return;
    }
    if (context.parmPrintSettings().lacDestinationSettings().skipDelivery())
    {
        return;
    }

    LACAttachmentFile fileToAdd = LACAttachmentFile::newFromDocuRef(docuRef);
    context.attachFile(LACAttachWithInstruction::newAttachWithInstruction(fileToAdd, LACAttachmentDeliveryMode::URL));
}

