}

// Adding attachments via docuRef
[LACReportElementPropertiesAttribute('SYP4881777'), // Specify name of report element that will be created if this method is used in report query wizard, Label must be provided without prefix, language text can be added directly
 LACValueSourceAttribute(staticmethodStr(LACTutorialContextMethodsTutorial_Tutorial, LACAddAttachmentsTutorial), 'Adds attachments from all DocuRefs attached to the same record')] // Name and description on expression value lookup
public static void LACAddAttachmentsTutorial(DocuRef docuRef, LACContext context)
{
    str dataSourceName;
    if (!docuRef.isValueAttached() || !context.parmCustomCode()) 
    {
        return;
    }
    if (context.parmPrintSettings().lacDestinationSettings().skipDelivery()) // Destination is set that files will not be delivered
    {
        return;
    }
    if (context.parmValueSegment() && context.parmValueSegment().parent()) // Initializing dataSourceName from valueSegment
    {
        LACValueSegment parentSegment = context.parmValueSegment().parent();
        if (!(parentSegment is LACValueSegment_RelatedSource))
        {
            return;
        }
        dataSourceName = parentSegment.getDisplayValue();
    }
    else if (context.parmLACReportElement()) // Initializing dataSourceName from valueSegment
    {
        dataSourceName = context.parmLACReportElement().getReturnDSName(context.argsCache());
    }
    if (!dataSourceName)
    {
        return;
    }
    Set ignoreDocuRefSet = LACSaveReportFileToData::buildIgnoreSet(context.parmReportContractData().saveReportTo());  // Optional to ignore some of data sources due to process of document handling
    if (ignoreDocuRefSet.in(DocuRef.RecId))
    {
        return;
    }

    LACDocuRefSetup docuRefSetup;
    // getting pre-initialized map [DataSourceName->LACDocuRefSetup]
    LACRecordMap setupMap = context.parmCustomCode().docuRefLineAttachmentSettings(dataSourceName, context.parmPostProcessing()?context.parmPostProcessing().getDocumentType():LACOverlayDocumentType::None);
    if (setupMap)
    {
        LACRecordMapEnumerator setupMapEnumerator = setupMap.getEnumerator();
        while(setupMapEnumerator.moveNext())
        {
            docuRefSetup = setupMapEnumerator.currentValue();
            DocuTypeId typeId = docuRefSetup.fieldExpression(context.argsCache()).getField(LACSymbols::DocuRef_DocuType, context.parmPostProcessing(), context.parmReportContractData().parmReportName());
            LACTutorialContextMethodsTutorial_Tutorial::LACAddAttachmentsInternalTutorial(docuRefSetup, docuRef, typeId, context);
        }
    }

}

/// <summary>
///     Support method for LACAddAttachments
/// </summary>
/// <param name = "docuRefSetup">DocuRef setup</param>
/// <param name = "docuRef">DocuRef</param>
/// <param name = "typeId">Type Id</param>
/// <param name = "context">context</param>
private static void LACAddAttachmentsInternalTutorial(LACDocuRefSetup docuRefSetup, DocuRef docuRef, DocuTypeId typeId, LACContext context)
{
    DocuRef allDocuRefsOnSameRecord;
    while select allDocuRefsOnSameRecord
                where allDocuRefsOnSameRecord.RefRecId == DocuRef.RefRecId &&
                      allDocuRefsOnSameRecord.RefTableId == DocuRef.RefTableId &&
                      allDocuRefsOnSameRecord.Restriction == docuRefSetup.DocuRestriction &&
                      allDocuRefsOnSameRecord.TypeId == typeId
    {
        if (docuRefSetup.ActiveCustomPort && docuRefSetup.ActiveFax && docuRefSetup.ActivePDF && docuRefSetup.ActivePrinter)
        {
            LACAttachmentFile fileToAdd = LACAttachmentFile::newFromDocuRef(allDocuRefsOnSameRecord);
            context.attachFile(LACAttachWithInstruction::newAttachWithInstruction(fileToAdd, docuRefSetup.AttachmentDeliveryMode));
        }
        else
        {
            if (docuRefSetup.ActiveCustomPort)
            {
                LACAttachmentFile fileToAdd = LACAttachmentFile::newFromDocuRef(allDocuRefsOnSameRecord);
                fileToAdd.onlyToDestinationType = LACDestTypes4Print::CustomPort;
                context.attachFile(LACAttachWithInstruction::newAttachWithInstruction(fileToAdd, docuRefSetup.AttachmentDeliveryMode));
            }
            if (docuRefSetup.ActiveFax)
            {
                LACAttachmentFile fileToAdd = LACAttachmentFile::newFromDocuRef(allDocuRefsOnSameRecord);
                fileToAdd.onlyToDestinationType = LACDestTypes4Print::Fax;
                context.attachFile(LACAttachWithInstruction::newAttachWithInstruction(fileToAdd, docuRefSetup.AttachmentDeliveryMode));
            }
            if (docuRefSetup.ActivePDF)
            {
                LACAttachmentFile fileToAdd = LACAttachmentFile::newFromDocuRef(allDocuRefsOnSameRecord);
                fileToAdd.onlyToDestinationType = LACDestTypes4Print::Email;
                context.attachFile(LACAttachWithInstruction::newAttachWithInstruction(fileToAdd, docuRefSetup.AttachmentDeliveryMode));
            }
            if (docuRefSetup.ActivePrinter)
            {
                LACAttachmentFile fileToAdd = LACAttachmentFile::newFromDocuRef(allDocuRefsOnSameRecord);
                fileToAdd.onlyToDestinationType = LACDestTypes4Print::Printer;
                context.attachFile(LACAttachWithInstruction::newAttachWithInstruction(fileToAdd, docuRefSetup.AttachmentDeliveryMode));
            }
        }
    }
}

/// <summary>
///     This method creates DocumentTitle element for replacement reports
/// </summary>
/// <param name = "common">Any table</param>
/// <param name = "context">LACContext</param>
/// <returns>Original document title</returns>
[LACReportElementPropertiesAttribute('SYS81383'), // Element name when used in wizard
 LACValueSourceAttribute(staticmethodStr(LACTutorialContextMethodsTutorial_Tutorial, LACOriginalReport_DocumentTitleTutorial), 'Gets original report document title')] // Label must be provided without prefix, language text can be added directly
public static str LACOriginalReport_DocumentTitleTutorial(Common common, LACContext context)
{
    MapEnumerator mapEnum = context.parmParametersMap().getEnumerator();
    str fromOrig, fromCurrent;
    while(mapEnum.moveNext())
    {
        if (mapEnum.currentKey() like '*#DocumentTitle') // If parameter name is ReportName#DocumentTitle this is automatically initialized from original report
        {
            fromOrig = conPeek(mapEnum.currentValue(), 2); // create element with string of document title
        }
        if (mapEnum.currentKey() like '*#ReportTitle') // If parameter name is ReportName#ReportTitle this is automatically initialized from original report like PSAInvoice
        {
            fromOrig = conPeek(mapEnum.currentValue(), 2); // create element with string of report title
        }
        if (mapEnum.currentKey() == 'DocumentTitle') // If parameter name is DocumentTitle
        {
            fromCurrent = conPeek(mapEnum.currentValue(), 2); // create element with string of document title
        }
        if (mapEnum.currentKey() == 'ReportTitle') // 2018.06.17 #536 287@365 for PSAInvoice
        {
            fromCurrent = conPeek(mapEnum.currentValue(), 2); // create element with string of document title
        }
    }
    if (fromOrig)   // If DocumentTitle or ReportTitle found in original report
    {
        return fromOrig;
    }
    return fromCurrent; // DocumentTitle or ReportTitle from current report
}

/// <summary>
///     This method illustrates how LAC context method is added as extension to CustTable
/// </summary>
/// <param name = "_custTable">Record identifier for CustTable</param>
/// <param name = "context">LACContext object</param>
public static void LACTutorialContextTutorial(CustTable _custTable, LACContext context)
{
    void insertDocuRef(SalesTable salesTable, XmlNode detailNode)
    {
        DocuRef docuRef; // Adding sales table attachements to report, only for e-mailing
        while select docuRef // Selecting all sales order attachments
            where docuRef.RefTableId == salesTable.TableId &&
                  docuRef.RefRecId   == salesTable.RecId
        {
            LACAttachmentFile fileToAdd = LACAttachmentFile::newFromDocuRef(docuRef);
            fileToAdd.onlyToDestinationType = LACDestTypes4Print::Email;   // Specifying condition for e-mail only attachment (default for all LACDestTypes4Print::UsePredefinedDest)
            // if you like to rename attachment file, this can be done:
            fileToAdd.fileName = 'MyAttachmentFileName_' + SalesTable.SalesId + /* adding right extension */conPeek(fileNameSplit(fileToAdd.fileName), 3); // You can rename attachment to desired file name
            context.attachFile(fileToAdd); // Adding file to attachments list
            // Alternative option adding file inline
            if (docuRef.fileExtension() == '.jpg')
            {
                context.newElementAzureUrlGUID('PictureURL', DocuRef.docuValue().FileId, detailNode); // Picture URL
                context.newElementFileNameOrData('PictureEmbeddedBase64', DocuRef.docuValue().getFileData(), detailNode); // Picture embedded as Base64 string (use with caution, as XML file will be big!)
            }
        }
    }
    Args arg = context.parmReportContractData().parmExecutionInfo().parmControllerArgs();
    // Creating section with elements
    XmlNode sectionNode  = context.newSection('MyCustomSectionInReport');
    // Report args demo
    if (arg)
    {
        info(strFmt('Tutorial context: Report caller MenuItemName = %1 (%2)', arg.menuItemName(), arg.menuItemType()));
    }
    // Label demo
    context.newLabel('Label', 'ElectronicReporting:Report', sectionNode); // Label id without prefix, so it's not translated to user interface language, as literalStr is not stable
    context.newLabel('LabelInDanish', 'ElectronicReporting:Report', sectionNode, 'da');
    // Creating report name element within section
    context.newElement('ReportName',        context.parmReportContractData().parmReportName(), sectionNode);
    // Creating report language id within section
    context.newElement('ReportLanguageId',  context.parmReportContractData().parmLanguageId(), sectionNode);
    // For SSRS reports, you can identify if it's copy/original report execution
    context.newElement('CopyOriginal', context.parmPrintSettings().lacDestinationSettings().printCopyOriginal(), sectionNode);

    // Disabling overlay (you can also append or overwrite overlays)
    context.overlay(LACManualOverwriteType::Disabled); // LACManualOverwriteType::Append, "MyOverlayId"

    // If you like to use different file name for report, there is possibility to overwrite default generated report file name.
    context.parmCustomReportFileName('MyReportFileName'); // This will be used for XML and PDF file names
    // Setting instruction to save report after processing into Docu structure
    context.saveReportTo(DocuRestriction::External, 'File', _custTable, 'Tutorial report attachment description', 'Tutorial notes for attachment', 'MyReport.pdf');

    // Build list of report parameters
    XmlNode parametersParent = context.newSection('ReportParameters', sectionNode);
    MapEnumerator mapEnum = context.parmParametersMap().getEnumerator();
    while(mapEnum.moveNext())
    {
        anytype value = context.getParameter(mapEnum.currentKey());
        context.newElement(strReplace(strReplace(mapEnum.currentKey(), '@',''), num2Char(40), ''), strReplace(strReplace(value, '@',''), num2Char(40), ''), parametersParent);
    }
    // Enums
    // By name (symbol value), this is language indifferent value
    context.newElement('EnumDemo_Name', LACUtils::enum2Symbol(enumNum(LACAzureType), LACAzureType::ServiceBus), sectionNode);
    // By label works as default, depends on report language
    context.newElement('EnumDemo_Label', LACAzureType::ServiceBus, sectionNode);

    // Building section with all customer sales orders
    XmlNode     salesOrdersSection = context.newSection('SalesOrders', sectionNode);
    Query       query = new Query();
    query.addDataSource(tableNum(SalesTable));
    QueryRun    queryRun = new QueryRun(query);

    // Setting query range from available CustTable record
    queryRun.query().dataSourceTable(tableNum(SalesTable)).addRange(fieldNum(SalesTable, CustAccount)).value(_custTable.AccountNum);
    SalesTable  salesTable;
    // Create labels for details nodes
    context.newLabelsFromRecord(SalesTable, tableFieldGroupStr(SalesTable, Overview), salesOrdersSection);
    while (queryRun.next())
    {
        salesTable = queryRun.get(tableNum(SalesTable));
        // Create separate Detail section for each sales order
        XmlNode detailNode = context.newSection('Detail', salesOrdersSection);

        // Add fields from overview group
        context.newElementsFromRecord(SalesTable, tableFieldGroupStr(SalesTable, Overview), detailNode);
        // Formatting AmmountInvoiced by report default number format, and adding number of decimals specified on EDT AmountCur
        context.newElement('DiscPercent', salesTable.DiscPercent, detailNode, ExtendedTypeNum(AmountCur));
        // Formatting AmountDelivered by completely custom format, where groups separated by fixed char ',' and decimals by '.'. Adding 5 places for numer of decimals
        context.newElement('DiscPercentCustom', context.convert2CultureStrCustom(salesTable.DiscPercent, '###(,)##0[.]##', 5), detailNode);
        // Here is example how to add attachments that are saved in DocuRef
        insertDocuRef(salesTable, detailNode); // inserting docuRefNodes
        // Here is example how to add attachments that are saved in LACArchive
        CustConfirmJour confirmJour;
        select firstonly confirmJour
            where confirmJour.SalesId == SalesTable.SalesId;
        if (confirmJour)
        {
            // Finding last archive
            LACArchive archive = LACArchive::findLastArchive(confirmJour);
            if (archive)
            {
                LACArchiveData archiveData = LACArchiveData::find(archive.Id, LACFileType::PDF);
                if (archiveData)
                {
                    // Loading XML file from archive
                    LACAttachmentFile fileToAdd = LACAttachmentFile::newFromLACArchiveData(archiveData);
                    // Attaching XML file
                    context.attachFile(fileToAdd);
                }
            }
        }
    }
}

/// Here is example how the same context method can be reused from two different tables.
/// We can use table maps to link fields together
public static void buildCustVendDetailsTutorial(CustVendTable custVendTableMap, LACContext context)
{
    XmlNode sectionNode = context.newSection('EntityDetails');
    context.newElement('AccountNum', custVendTableMap.AccountNum, sectionNode);
    context.newElement('Name', custVendTableMap.name(), sectionNode);
    context.newElement('Balance', custVendTableMap.balanceMST(), sectionNode);
}

// This method then can be reused from CustTable
public static void LACTutorialCustEntityDetailsTutorial(CustTable _custTable, LACContext context)
{
    LACTutorialContextMethodsTutorial_Tutorial::buildCustVendDetailsTutorial(_custTable, context);
}

// This method then can be reused from VendTable
public static void LACTutorialVendEntityDetailsTutorial(VendTable _vendTable, LACContext context)
{
    LACTutorialContextMethodsTutorial_Tutorial::buildCustVendDetailsTutorial(_vendTable, context);
}

