/// <summary>
///     This method illustrates how to Explode Project tree in the report, where Projects can be created as tree structure, linked through ParentId
/// </summary>
/// <param name = "_record">Project record (Parent)</param>
/// <param name = "context">LACContext object</param>
public static str LACExplodeTmp_ByProjTableTutorial(ProjTable  _projTable, LACContext context)
{
    LACExplodeTmp                    explodeTmp = context.getTMPBuffer(tableStr(LACExplodeTmp), true);
    Int                              counter = 0;

    counter = LACTutorialContextMethodsTutorial_Tutorial::explodeProjTable(_projTable, explodeTmp, 1, counter, tableId2Name(_projTable.TableId), _projTable.RecId);
    return strFmt('%1 ref record(s) created.', counter);
}

/// <summary>
///   This method creates Temporary table to link exploded sub-Project records
/// </summary>
/// <param name = "_projTable">Parent project table</param>
/// <param name = "_explodeTmp">Tempoary table used as link</param>
/// <param name = "_level">Level of depth</param>
/// <param name = "_counter">Counter of records created above</param>
/// <param name = "_parentRefTableName">Parent table name</param>
/// <param name = "_parentRefRecId"Parent record Id></param>
/// <returns>Number of records created</returns>
private static Int explodeProjTable(ProjTable _projTable, LACExplodeTmp _explodeTmp, int _level, int _counter, TableName _parentRefTableName, RefRecId _parentRefRecId)
{
    int        counter = _counter;

    if (_projTable.ProjId)
    {
        ProjTable        projTableChild;
        while select projTableChild
            order by ProjId
            where projTableChild.ParentId == _projTable.ProjId
        {
            _explodeTmp.initValue();
            _explodeTmp.ParentRefTableName = _parentRefTableName;
            _explodeTmp.ParentRefRecId = _parentRefRecId;
            _explodeTmp.RefTableName = _parentRefTableName;
            _explodeTmp.RefRecId = projTableChild.RecId;
            _explodeTmp.Sorting = counter;
            _explodeTmp.Level = _level;
            _explodeTmp.insert();
            counter++;

            counter = LACTutorialContextMethodsTutorial_Tutorial::explodeProjTable(projTableChild, _explodeTmp, _level+1, counter, _parentRefTableName, _parentRefRecId);
        }
    }
    return counter;
}

/// <summary>
///     This method illustrates how to Explode BOM tree in the report, where BOMs can be created as tree structure
/// </summary>
/// <param name = "_record">InventTable record</param>
/// <param name = "context">LACContext object</param>
public static str LACExplodeTmp_ByInventTableTutorial(InventTable _inventTable, LACContext context)
{
    LACExplodeTmp                    explodeTmp = context.getTMPBuffer(tableStr(LACExplodeTmp), true);
    Int                              counter = 0;

    counter = LACTutorialContextMethodsTutorial_Tutorial::explodeBOM(_inventTable.ItemId, systemDateGet(), 1, InventDim::findOrCreateBlank(), explodeTmp, 1, counter, tableId2Name(_inventTable.TableId), _inventTable.RecId);
    return strFmt('%1 ref record(s) created.', counter);
}

/// <summary>
///   This method creates Temporary table to link exploded sub-BOM records
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_date">Date for active BOM versions</param>
/// <param name = "_qtyFrom">Qty</param>
/// <param name = "_inventDim">InventDim</param>
/// <param name = "_explodeTmp">_explodeTmp buffer</param>
/// <param name = "_level">Level</param>
/// <param name = "_counter">Records counter</param>
/// <param name = "_parentRefTableName">Table name</param>
/// <param name = "_parentRefRecId">Parent record RecId</param>
/// <returns></returns>
private static Int explodeBOM(ItemId _itemId, date _date, Qty _qtyFrom, InventDim _inventDim, LACExplodeTmp _explodeTmp, int _level, int _counter, TableName _parentRefTableName, RefRecId _parentRefRecId)
{
    BOMVersion bomVersion = bomVersion::findActive(_itemId, _date, _qtyFrom, _inventDim);
    int        counter = _counter;

    if (bomVersion.RecId)
    {
        BOM        bom;
        while select bom
                index hint NumIdx
                where bom.BOMId == bomVersion.BOMId
        {
            _explodeTmp.initValue();
            _explodeTmp.ParentRefTableName = _parentRefTableName;
            _explodeTmp.ParentRefRecId = _parentRefRecId;
            _explodeTmp.RefTableName = tableStr(bom);
            _explodeTmp.RefRecId = bom.RecId;
            _explodeTmp.Sorting = counter;
            _explodeTmp.Level = _level;
            _explodeTmp.insert();
            counter++;

            counter = LACTutorialContextMethodsTutorial_Tutorial::explodeBOM(bom.ItemId, _date, 1, bom.inventDim(), _explodeTmp, _level+1, counter, _parentRefTableName, _parentRefRecId);
        }
    }
    return counter;
}
